package setup

import (
	"io"
	"path/filepath"
	"strings"

	"github.com/zextras/carbonio-configd/internal/getopt"
)

// The commands of zmdhparam and the number of bits it generated by default.
const (
	dhCmdGet      = "get"
	dhCmdSet      = "set"
	dhDefaultBits = 2048
)

// dhOptions are the command and the options of zmdhparam.
type dhOptions struct {
	Command string
	In, Out string // -in, -out: a file, "-" for stdin/stdout
	HasIn   bool
	HasOut  bool
	// Bits is the size asked with -new; HasNew tells that -new was given
	// (with no number, Bits is 0).
	Bits   int
	HasNew bool
	// Debug is the -debug level: 0 off, a bare -debug is 1.
	Debug     int
	Help, Man bool
}

// The names of the options.
const (
	dhOptIn    = "in"
	dhOptOut   = "out"
	dhOptLDAP  = "ldap"
	dhOptNew   = "new"
	dhOptHelp  = "help"
	dhOptMan   = "man"
	dhOptDebug = "debug"
)

// dhOptionKinds are the options of Opts::_process_options (Getopt::Long
// "in=s", "out=s", "ldap", "new:i", "help", "man", "debug:1"), by name.
var dhOptionKinds = map[string]getopt.Kind{
	dhOptIn: getopt.String, dhOptOut: getopt.String, dhOptLDAP: getopt.Flag, dhOptNew: getopt.OptInt,
	dhOptHelp: getopt.Flag, dhOptMan: getopt.Flag, dhOptDebug: getopt.OptInt,
}

// dhOptionNames are the options a command takes: none of the file and size
// options without a valid command (the script parsed only -help, -man and
// -debug then), and -new only for set.
func dhOptionNames(cmd string) []string {
	switch cmd {
	case dhCmdGet:
		return []string{dhOptIn, dhOptOut, dhOptLDAP, dhOptHelp, dhOptMan, dhOptDebug}
	case dhCmdSet:
		return []string{dhOptIn, dhOptOut, dhOptLDAP, dhOptNew, dhOptHelp, dhOptMan, dhOptDebug}
	}

	return []string{dhOptHelp, dhOptMan, dhOptDebug}
}

// dhParse is the result of reading the command line: the options, the
// problems the script reported before its usage text (errs), and whether the
// options parsed at all (when they did not, the details are on stderr and
// only the short usage is printed).
type dhParse struct {
	opts   dhOptions
	errs   []string
	parsed bool
}

// parseDHParamArgs reads args as the script did: the command first (get or
// set), then Getopt::Long options (a single or double dash, any case, a unique
// abbreviation, "-name=value" or "-name value"), mixed with arguments that
// the script then rejected as unexpected. Messages of the option parser go to
// stderr.
func parseDHParamArgs(args []string, stderr io.Writer) *dhParse {
	p := &dhParse{}

	if len(args) == 0 || strings.HasPrefix(args[0], "-") {
		p.errs = append(p.errs, "a command must be specified")
	} else if args[0] == dhCmdGet || args[0] == dhCmdSet {
		p.opts.Command, args = args[0], args[1:]
	}

	var specs []getopt.Spec

	for _, n := range dhOptionNames(p.opts.Command) {
		specs = append(specs, getopt.Spec{Names: []string{n}, Kind: dhOptionKinds[n]})
	}

	r := getopt.Parse(args, specs, stderr)
	o := &p.opts
	p.parsed = r.AllGood

	o.In, o.HasIn = r.Strs[dhOptIn], r.Has(dhOptIn)
	o.Out, o.HasOut = r.Strs[dhOptOut], r.Has(dhOptOut)
	o.Bits, o.HasNew = r.Ints[dhOptNew], r.Has(dhOptNew)
	o.Help, o.Man = r.Has(dhOptHelp), r.Has(dhOptMan)

	if r.Has(dhOptDebug) {
		o.Debug = 1
		if !r.Bare[dhOptDebug] {
			o.Debug = max(r.Ints[dhOptDebug], 0)
		}
	}

	p.check(r.Rest)

	return p
}

// check adds the problems the script found in the options as a whole: more
// than the command and its options, -in and -out naming one file, and for
// set neither or both of -new and -in.
func (p *dhParse) check(rest []string) {
	o := &p.opts

	if len(rest) > 0 {
		p.errs = append(p.errs, "unexpected argument(s): "+strings.Join(rest, " "))
	}

	if o.HasIn && o.HasOut && o.In != "-" && o.Out != "-" && dhSameFile(o.In, o.Out) {
		p.errs = append(p.errs, "-in and -out can not match")
	}

	if o.Command != dhCmdSet {
		return
	}

	switch {
	case o.HasNew && o.HasIn:
		p.errs = append(p.errs, "-new and -in are exclusive arguments")
	case !o.HasNew && !o.HasIn:
		p.errs = append(p.errs, "-new or -in must be specified")
	}
}

// dhSameFile is whether two paths are the same file, as Cwd::abs_path told.
func dhSameFile(a, b string) bool {
	pa, errA := filepath.Abs(a)
	pb, errB := filepath.Abs(b)

	return errA == nil && errB == nil && pa == pb
}
